/**
 * Axis-aligned box in 2D, defined by min/max corners (inclusive bounds).
 */
export interface AABB {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface SweepResult {
  /**
   * Time of impact in [0, 1], as a fraction of the full velocity applied
   * this step. `1` means the boxes never collide during this step.
   */
  toi: number;
  /** True if the moving box hits the static box at some t in [0, 1]. */
  hit: boolean;
  /**
   * Surface normal on the static box pointing back toward the moving box
   * at the time of impact. Zero vector when there is no hit.
   */
  nx: number;
  ny: number;
}

/**
 * Swept-AABB time-of-impact via interval slicing on each axis.
 *
 * For each axis we compute the entry/exit times of the interval overlap:
 *   - entry time: when the boxes first touch along that axis
 *   - exit time:  when they stop overlapping along that axis
 *
 * The boxes are disjoint until the LAST axis-entry happens and separate
 * again after the FIRST axis-exit. So a hit exists iff
 *   maxEntry <= minExit  and  maxEntry >= 0  (hit within the step)
 * and the TOI is that maxEntry.
 */
export function sweepAABB(
  moving: AABB,
  velX: number,
  velY: number,
  wall: AABB,
): SweepResult {
  // Entry/exit intervals per axis. Start "open" for axes with no motion.
  let entry = -Infinity;
  let exit = Infinity;
  let normalAxis: "x" | "y" | null = null;
  let normalSign = 0;

  const processAxis = (
    mMin: number,
    mMax: number,
    v: number,
    sMin: number,
    sMax: number,
    axis: "x" | "y",
  ): void => {
    if (v === 0) {
      if (mMax < sMin || mMin > sMax) {
        // Moving box is disjoint from the wall along this axis and never
        // moves toward it: no possible collision.
        exit = -Infinity; // forces miss below
      }
      return;
    }

    const tEnter = ((v > 0 ? sMin : sMax) - (v > 0 ? mMax : mMin)) / v;
    const tLeave = ((v > 0 ? sMax : sMin) - (v > 0 ? mMin : mMax)) / v;
    // tEnter <= tLeave by construction.

    if (tEnter > entry) {
      entry = tEnter;
      normalAxis = axis;
      normalSign = v > 0 ? -1 : 1; // normal opposes travel direction
    }
    if (tLeave < exit) {
      exit = tLeave;
    }
  };

  processAxis(moving.minX, moving.maxX, velX, wall.minX, wall.maxX, "x");
  processAxis(moving.minY, moving.maxY, velY, wall.minY, wall.maxY, "y");

  // No hit if the swept intervals never overlap, or the collision happens
  // entirely before/at the start of the step beyond [0,1] reach.
  const hit = entry !== -Infinity && exit !== -Infinity && entry <= exit && entry >= 0 && entry <= 1;
  if (!hit) {
    return { toi: 1, hit: false, nx: 0, ny: 0 };
  }

  const t = Math.min(entry, 1);
  return {
    toi: t,
    hit: true,
    nx: normalAxis === "x" ? normalSign : 0,
    ny: normalAxis === "y" ? normalSign : 0,
  };
}

/**
 * Convenience: naive discrete overlap test after applying the full step.
 * Used to demonstrate tunneling.
 */
export function overlapsAfterStep(
  moving: AABB,
  velX: number,
  velY: number,
  wall: AABB,
): boolean {
  const moved: AABB = {
    minX: moving.minX + velX,
    minY: moving.minY + velY,
    maxX: moving.maxX + velX,
    maxY: moving.maxY + velY,
  };
  return (
    moved.minX <= wall.maxX &&
    moved.maxX >= wall.minX &&
    moved.minY <= wall.maxY &&
    moved.maxY >= wall.minY
  );
}

/**
 * Sliding response: move to the point of impact, then apply the remaining
 * velocity only along axes not blocked by the hit normal. The returned box
 * is guaranteed non-overlapping with the wall.
 */
export function slideResponse(
  moving: AABB,
  velX: number,
  velY: number,
  wall: AABB,
): AABB & { toi: number; nx: number; ny: number } {
  const r = sweepAABB(moving, velX, velY, wall);
  if (!r.hit) {
    return { ...moving, minX: moving.minX + velX, minY: moving.minY + velY, maxX: moving.maxX + velX, maxY: moving.maxY + velY, toi: 1, nx: 0, ny: 0 };
  }
  // Small epsilon so the resting position sits just outside contact.
  const eps = 1e-6;
  const dx = r.nx !== 0 || r.ny !== 0 ? velX * r.toi + r.nx * eps : velX;
  const dy = r.nx !== 0 || r.ny !== 0 ? velY * r.toi + r.ny * eps : velY;
  let outVelX = velX * (1 - r.toi);
  let outVelY = velY * (1 - r.toi);
  if (r.nx !== 0) outVelX = 0;
  if (r.ny !== 0) outVelY = 0;
  return {
    minX: moving.minX + dx + outVelX,
    minY: moving.minY + dy + outVelY,
    maxX: moving.maxX + dx + outVelX,
    maxY: moving.maxY + dy + outVelY,
    toi: r.toi,
    nx: r.nx,
    ny: r.ny,
  };
}

