import { describe, it, expect } from "vitest";
import { sweepAABB, overlapsAfterStep, slideResponse, type AABB } from "./sweep.js";

const box = (minX: number, minY: number, maxX: number, maxY: number): AABB => ({
  minX,
  minY,
  maxX,
  maxY,
});

describe("tunneling: discrete check misses, sweep catches", () => {
  // A 4px-wide bullet fired at 300px per 1/60s step toward a 2px-thick wall.
  const bullet = box(0, 10, 4, 14);
  const vx = 300;
  const wall = box(100, 0, 102, 50); // 2px thick, spans the bullet's row

  it("naive discrete overlap after the full step misses the wall entirely", () => {
    // Bullet teleports from x:[0,4] to x:[300,304]; the wall at x:[100,102]
    // is jumped clean over between samples.
    expect(overlapsAfterStep(bullet, vx, 0, wall)).toBe(false);
  });

  it("swept AABB detects the pass-through hit", () => {
    const r = sweepAABB(bullet, vx, 0, wall);
    expect(r.hit).toBe(true);
    // Contact begins when leading edge (x=4) reaches wall's left face (x=100):
    // t = 96 / 300 = 0.32
    expect(r.toi).toBeCloseTo(0.32, 6);
    expect(r.nx).toBe(-1);
    expect(r.ny).toBe(0);
  });
});

describe("TOI correctness against hand-computed values", () => {
  it("horizontal approach onto vertical wall", () => {
    // Box x:[0,4] moving right at 300 into wall left face at x=100.
    // tEnter = (100 - 4) / 300 = 0.32 ; tLeave = 102/300 = 0.34 > tEnter.
    const r = sweepAABB(box(0, 10, 4, 14), 300, 0, box(100, 0, 102, 50));
    expect(r.hit).toBe(true);
    expect(Math.abs(r.toi - 96 / 300)).toBeLessThan(1e-6);
  });

  it("diagonal movement picks the later axis entry", () => {
    // X enters at (50 - 2)/100 = 0.48 ; Y already overlapping along its range
    // while drifting, exits far later. Hit is governed by X at exactly 0.48.
    const r = sweepAABB(box(0, 0, 2, 2), 100, 50, box(50, -100, 52, 100));
    expect(r.hit).toBe(true);
    expect(Math.abs(r.toi - 0.48)).toBeLessThan(1e-6);
    expect(r.nx).toBe(-1);
  });

  it("misses report hit=false and toi=1", () => {
    const r = sweepAABB(box(0, 0, 2, 2), 300, 0, box(500, 500, 502, 600));
    expect(r.hit).toBe(false);
    expect(r.toi).toBe(1);
  });

  it("hit beyond one step clamps out of range", () => {
    // Would reach the wall at t = 98/60 > 1 within this step's velocity budget.
    const r = sweepAABB(box(0, 0, 2, 2), 60, 0, box(100, -50, 102, 50));
    expect(r.hit).toBe(false);
  });
});

describe("sliding response using the returned normal", () => {
  it("box slides along a floor and stays outside the wall", () => {
    // Box falling diagonally onto the top face of a floor slab.
    const mover = box(0, 1, 10, 11);
    const floor = box(-1000, -1, 1000, 0);
    const r = slideResponse(mover, 30, -20, floor);

    // Impact at t = (0 - 1) / -20 = 0.05, normal points up.
    expect(r.ny).toBe(1);
    expect(Math.abs(r.toi - 0.05)).toBeLessThan(1e-6);

    // Vertical motion is cancelled by the normal; horizontal continues:
    // x = 0 + 30*0.05 + 30*0.95 = 30, resting epsilon above the surface.
    expect(r.minX).toBeCloseTo(30, 6);

    const separated =
      r.maxY <= floor.minY ||
      r.minY >= floor.maxY ||
      r.maxX <= floor.minX ||
      r.minX >= floor.maxX;
    expect(separated).toBe(true);
  });

  it("vertical-wall slide preserves downward fall while blocking sideways travel", () => {
    const mover = box(0, 0, 10, 10);
    const pillar = box(50, -1000, 52, 1000);
    const r = slideResponse(mover, -40, -25, pillar);

    expect(r.nx).toBe(-1);
    expect(Math.abs(r.toi - (50 - 10) / 40)).toBeLessThan(1e-6);

    const separated =
      r.maxX <= pillar.minX || r.minX >= pillar.maxX ||
      r.maxY <= pillar.minY || r.minY >= pillar.maxY;
    expect(separated).toBe(true);
    // Fell the full remaining distance despite the horizontal block.
    expect(r.maxY).toBeCloseTo(mover.maxY - 25, 6);
  });

  it("unobstructed motion passes through unchanged", () => {
    const mover = box(0, 0, 10, 10);
    const r = slideResponse(mover, 7, -3, box(400, 400, 402, 402));
    expect(r.minX).toBe(7);
    expect(r.minY).toBe(-3);
  });
});

